// Create multiple exercise formats from each sentence base.
const BANK=[];let qid=1;
function shuffleTokens(parts){return parts.map(x=>x.t).sort(()=>Math.random()-.5)}
function addQ(q){q.id=qid++;BANK.push(q)}
for(const b of BASE){
  addQ({...b,type:'reorder',tokens:b.parts.map(x=>x.t)});
  addQ({...b,type:'skeleton',roles:b.parts.map(x=>(ROLE[x.r]||x.r)+': '+x.t)});
  // Position exercise for grammars where one marker is central and unique.
  const markers={zai:'正在',gen_yiqi:'一起',bi:'比',jiu_cai:null,youdian:'有点儿',keneng:'可能',zui:'最',hy_na:'哪',hy_shenme_o:'什么',hy_shei:'谁',hy_ne_context:'呢',hy_keyi:'可以'};
  const marker=markers[b.grammar]; if(marker && b.parts.filter(x=>x.t===marker).length===1){addQ({...b,type:'place',target:marker,base:b.parts.filter(x=>x.t!==marker).map(x=>x.t).join(' / ')})}
}
