window.SL_VOCAB_1000=VOCAB;
window.SL_SENTENCE_BANK=BANK;
window.SL_GRAMMAR_META=GRAMMAR;
window.SL_ROLE_META=ROLE;
const SL_STORE = 'hskSentenceLabIntegrated_v1';
let slState = loadSL();
let slSession = [];
let slCurrent = 0;
let slAnswered = false;

const root = document.getElementById('view-sentence-lab');
if(!root) return;
const q = sel => root.querySelector(sel);
const qa = sel => [...root.querySelectorAll(sel)];

function loadSL(){
  try{
    const x = JSON.parse(localStorage.getItem(SL_STORE)||'{}');
    return {attempts:Array.isArray(x.attempts)?x.attempts:[], wrong:Array.isArray(x.wrong)?x.wrong:[]};
  }catch{return {attempts:[],wrong:[]}}
}
function saveSL(){
  localStorage.setItem(SL_STORE,JSON.stringify(slState));
  updateSLStats();
}
function nrm(s){return (s||'').trim().replace(/[，。！？,.!?；;：:\s]/g,'').toLowerCase()}
function sameSL(a,b){return nrm(a)===nrm(b)}
function slAcceptedAnswers(item){
  const arr=Array.isArray(item?.acceptedAnswers)&&item.acceptedAnswers.length?item.acceptedAnswers:[item?.answer];
  return [...new Set(arr.filter(Boolean))];
}
function sameSLItem(ans,item){return slAcceptedAnswers(item).some(a=>sameSL(ans,a))}
function opt(el,arr,val=x=>x,label=x=>x){el.innerHTML=arr.map(x=>`<option value="${val(x)}">${label(x)}</option>`).join('')}

function setSLTab(name){
  const main=name==='prep'?'prep':'unified';
  qa('.sl-tab').forEach(b=>b.classList.toggle('active',b.dataset.slTab===main));
  q('#slPanelUnified')?.classList.toggle('hidden',name!=='unified');
  q('#slPanelPrep').classList.toggle('hidden',name!=='prep');
  q('#slPanelPractice').classList.toggle('hidden',name!=='practice');
  q('#slPanelGrammar').classList.toggle('hidden',name!=='grammar');
  q('#slPanelErrors').classList.toggle('hidden',name!=='errors');
  if(name==='prep'){renderPrepCatalog();updatePrepStats()}
  if(name==='unified') renderUnifiedCatalog();
  if(name==='errors') renderSLErrors();
}
qa('.sl-tab').forEach(b=>b.addEventListener('click',()=>setSLTab(b.dataset.slTab)));
qa('[data-sl-open-tool]').forEach(b=>b.addEventListener('click',()=>setSLTab(b.dataset.slOpenTool)));

function updateSLStats(){
  const a=slState.attempts.length,c=slState.attempts.filter(x=>x.correct).length;
  q('#slBankCount').textContent=BANK.length;
  q('#slAttemptCount').textContent=a;
  q('#slAccuracy').textContent=a?Math.round(c*100/a)+'%':'0%';
  const sTotal=slSession.length;
  const sDone=Math.min(slCurrent+(slAnswered?1:0),sTotal);
  const sAttempts=slState.attempts.slice(-Math.max(0,sDone));
  const sCorrect=sAttempts.filter(x=>x.correct).length;
  q('#slSessionStats').innerHTML=`
    <div class="statline"><span>Ngân hàng</span><b>${BANK.length} câu</b></div>
    <div class="statline"><span>Phiên hiện tại</span><b>${sTotal?`${sDone}/${sTotal}`:'—'}</b></div>
    <div class="statline"><span>Đúng trong phần đã làm</span><b>${sDone?sCorrect:'—'}</b></div>
    <div class="statline"><span>Lỗi đã lưu</span><b>${slState.wrong.length}</b></div>`;
}


function slBaseByLevel(level){
  return BANK.filter(x=>eligibleSL(x,level))
}
function slGrammarOptions(level){
  const ids=[...new Set(slBaseByLevel(level).flatMap(x=>slGrammarIds(x)))];
  return ids.map(id=>G.get(id)).filter(Boolean).sort((a,b)=>a.name.localeCompare(b.name,'vi'))
}
function slQuestionWords(pool,level){
  const source=(VOCAB||[]).filter(w=>level==='ALL'||w.l===+level);
  const used=[];
  for(const w of source){
    if(!w?.h)continue;
    if(pool.some(item=>(item.answer||'').includes(w.h))) used.push(w)
  }
  return used.sort((a,b)=>{
    const pa=(a.p||'').localeCompare(b.p||'','en');
    return pa!==0?pa:(a.h||'').localeCompare(b.h||'','zh')
  })
}
function refreshSLGrammar(){
  const level=q('#slLevel').value;
  const previous=q('#slGrammar').value||'all';
  const gs=slGrammarOptions(level);
  q('#slGrammar').innerHTML='<option value="all">Tất cả ngữ pháp</option>'+gs.map(g=>`<option value="${g.id}">${g.name}</option>`).join('');
  if(previous==='all'||gs.some(g=>g.id===previous))q('#slGrammar').value=previous;
  else q('#slGrammar').value='all';
  refreshSLVocab()
}
function refreshSLVocab(){
  const level=q('#slLevel').value,g=q('#slGrammar').value||'all';
  const previous=q('#slVocab').value||'all';
  let pool=slBaseByLevel(level);
  if(g!=='all')pool=pool.filter(x=>slGrammarIds(x).includes(g));
  const words=slQuestionWords(pool,level);
  q('#slVocab').innerHTML='<option value="all">Tất cả từ vựng trong cấp</option>'+words.map(w=>`<option value="${w.h}">${w.h} · ${w.p||''} · ${w.m||''}</option>`).join('');
  if(previous==='all'||words.some(w=>w.h===previous))q('#slVocab').value=previous;
  else q('#slVocab').value='all';
  updateSLMatchInfo()
}
function currentSLPool(){
  const mode=q('#slMode').value||'all',
        g=q('#slGrammar').value||'all',
        level=q('#slLevel').value||'ALL',
        vocab=q('#slVocab').value||'all';
  return BANK.filter(x=>
    (mode==='all'||x.type===mode) &&
    (g==='all'||slGrammarIds(x).includes(g)) &&
    eligibleSL(x,level) &&
    (vocab==='all'||(x.answer||'').includes(vocab))
  )
}
function updateSLMatchInfo(){
  const pool=currentSLPool();
  const level=q('#slLevel').value;
  const g=q('#slGrammar').value||'all';
  const vocab=q('#slVocab').value||'all';
  const pieces=[level==='ALL'?'Tất cả cấp':`HSK${level}`];
  if(g!=='all')pieces.push(G.get(g)?.name||g);
  if(vocab!=='all')pieces.push(`từ “${vocab}”`);
  q('#slMatchInfo').textContent=`${pieces.join(' · ')} → ${pool.length} câu phù hợp`;
}
function renderSLGrammarByLevel(){
  const box=q('#slGrammarCards');
  box.innerHTML=[1,2,3].map(level=>{
    const ids=[...new Set(BANK.filter(x=>x.level===level).flatMap(x=>slGrammarIds(x)))];
    const gs=ids.map(id=>G.get(id)).filter(Boolean).sort((a,b)=>a.name.localeCompare(b.name,'vi'));
    return `<div class="sl-grammar-level-section">
      <div class="sl-grammar-level-head"><span class="sl-grammar-level-badge">HSK${level}</span><span class="sl-grammar-level-count">${gs.length} cấu trúc có bài luyện</span></div>
      <div class="sl-grammar-level-grid">${gs.map(g=>`
        <div class="sl-grammar-card">
          <b>${g.name}</b>
          <div class="formula">${g.formula}</div>
          <div class="level-tags"><span class="sl-mini-level">HSK${level}</span></div>
          <button type="button" class="btn secondary sl-quick" data-g="${g.id}" data-level="${level}" style="margin-top:10px">Luyện ở HSK${level}</button>
        </div>`).join('')}</div>
    </div>`
  }).join('');
  qa('.sl-quick').forEach(b=>b.addEventListener('click',()=>{
    setSLTab('practice');
    q('#slLevel').value=b.dataset.level;
    refreshSLGrammar();
    q('#slGrammar').value=b.dataset.g;
    refreshSLVocab();
    startSL();
  }))
}
function initSL(){
  opt(q('#slMode'),['all',...Object.keys(MODES)],x=>x,x=>x==='all'?'Tất cả dạng':MODES[x]);
  refreshSLGrammar();
  renderSLGrammarByLevel();
  q('#slLevel').addEventListener('change',()=>{
    refreshSLGrammar()
  });
  q('#slGrammar').addEventListener('change',()=>{
    refreshSLVocab()
  });
  q('#slVocab').addEventListener('change',updateSLMatchInfo);
  q('#slMode').addEventListener('change',updateSLMatchInfo);
  updateSLStats();
  renderSLErrors();
}
function eligibleSL(x,level){
  return level==='ALL' ? true : x.level===+level
}

function startSL(){
  window.SL_ACTIVE_PREP_ID=null;
  const n=+q('#slCount').value;
  const pool=currentSLPool();
  if(!pool.length){
    q('#slInitial').classList.add('hidden');
    q('#slQuizBody').classList.remove('hidden');
    q('#slQMode').textContent='Không có câu phù hợp';
    q('#slQSource').textContent='';
    q('#slQIndex').textContent='0';q('#slQTotal').textContent='0';
    q('#slQProgress').style.width='0%';
    q('#slQPrompt').innerHTML='<b>Chưa có câu phù hợp với tổ hợp cấp HSK · ngữ pháp · từ vựng · dạng bài này.</b><br><span class="mini">Hãy chọn “Tất cả từ vựng trong cấp”, “Tất cả ngữ pháp” hoặc đổi dạng bài.</span>';
    q('#slQTokens').innerHTML='';
    q('#slQAnswer').classList.add('hidden');
    q('#slCheck').classList.add('hidden');q('#slHint').classList.add('hidden');q('#slSkip').classList.add('hidden');
    q('#slFeedback').innerHTML='';q('#slAnalysis').classList.add('hidden');q('#slNextBar').classList.add('hidden');
    return
  }
  slSession=pool.slice().sort(()=>Math.random()-.5).slice(0,Math.min(n,pool.length));
  slCurrent=0;slAnswered=false;
  q('#slInitial').classList.add('hidden');
  q('#slQuizBody').classList.remove('hidden');
  renderSLQ();
}
q('#slStart').addEventListener('click',startSL);

function scrambledSL(parts){
  let a=parts.map(x=>x.t),orig=a.join('|'),tries=0;
  do{a=a.slice().sort(()=>Math.random()-.5);tries++}while(a.join('|')===orig&&tries<7);
  return a;
}
function renderSLQ(){
  if(slCurrent>=slSession.length){
    q('#slQMode').textContent='Hoàn thành';
    q('#slQSource').textContent='';
    q('#slQIndex').textContent=slSession.length;
    q('#slQTotal').textContent=slSession.length;
    q('#slQProgress').style.width='100%';
    q('#slQPrompt').innerHTML='<b>Hoàn thành phiên luyện.</b><br><span class="mini">Bạn có thể mở tab “Ôn lỗi” để xem lại các câu sai.</span>';
    q('#slQTokens').innerHTML='';
    q('#slQAnswer').classList.add('hidden');
    q('#slCheck').classList.add('hidden');q('#slHint').classList.add('hidden');q('#slSkip').classList.add('hidden');
    q('#slFeedback').innerHTML='';q('#slAnalysis').classList.add('hidden');q('#slNextBar').classList.add('hidden');
    updateSLStats(); return;
  }
  slAnswered=false;
  const item=slSession[slCurrent],g=G.get(activeSLGrammarId(item));
  q('#slQAnswer').classList.remove('hidden');q('#slCheck').classList.remove('hidden');q('#slHint').classList.remove('hidden');q('#slSkip').classList.remove('hidden');
  q('#slQIndex').textContent=slCurrent+1;q('#slQTotal').textContent=slSession.length;
  q('#slQProgress').style.width=(slCurrent/slSession.length*100)+'%';
  q('#slQMode').textContent=MODES[item.type]||item.type;q('#slQSource').textContent=item.displaySource||'';
  let prompt='',tokens=[];
  if(item.type==='reorder'||item.type==='skeleton'){prompt='Hãy gõ lại thành một câu đúng. Không cần kéo thả.';tokens=scrambledSL(item.parts)}
  else if(item.type==='place'){prompt=`Hãy gõ lại câu và đặt “${item.target}” vào đúng vị trí.`}
  else if(item.type==='fix'){prompt='Câu dưới đây sai. Hãy gõ lại câu đúng.'}
  else if(item.type==='translate'){prompt='Dịch sang tiếng Trung.'}
  if(item.type==='translate')prompt+=`<div style="margin-top:8px"><b>${item.vi}</b></div>`;
  if(item.type==='fix')prompt+=`<div style="font-family:var(--font-zh);font-size:26px;margin-top:8px">${item.wrong}</div>`;
  if(item.type==='place')prompt+=`<div style="font-family:var(--font-zh);font-size:23px;margin-top:8px">${item.base}</div>`;
  q('#slQPrompt').innerHTML=prompt;
  q('#slQTokens').innerHTML=tokens.map(t=>`<span class="sl-token">${t}</span>`).join('');
  q('#slQAnswer').value='';q('#slQAnswer').disabled=false;
  q('#slCheck').disabled=false;q('#slHint').disabled=false;
  q('#slFeedback').className='sl-feedback';q('#slFeedback').innerHTML='';
  q('#slAnalysis').classList.add('hidden');q('#slAnalysis').innerHTML='';
  q('#slNextBar').classList.add('hidden');
  const prepMeta=window.SL_ACTIVE_PREP_ID?PREP_GRAMMAR_BANK.find(x=>x.id===window.SL_ACTIVE_PREP_ID):null;
  q('#slMeta').innerHTML=`<span class="pill">${prepMeta?prepMeta.title:g.name}</span><span class="pill">HSK${prepMeta?prepMeta.level:item.level}</span><span class="pill">${prepMeta?'PREP · Bài '+String(prepMeta.lesson).padStart(2,'0'):(item.topic||'Tổng hợp')}</span>`;
  q('#slQAnswer').focus();
  updateSLStats();
}

function slAnalysisHTML(item){
  const g=G.get(activeSLGrammarId(item));
  const prepId=window.SL_ACTIVE_PREP_ID||null;
  const prepFormula=(prepId&&item?.prepFormulaMap?.[prepId])||g.formula;
  const prepTitle=(prepId&&item?.prepTitleMap?.[prepId])||g.name;
  const cleanParts=item.parts.filter(x=>!/[，。！？,.!?；;：:]/.test(x.t));
  const rows=cleanParts.map(x=>{
    const m=meta(x.t);
    return `<tr>
      <td style="font-family:var(--font-zh);font-size:18px">${x.t}</td>
      <td>${m.p||'—'}</td>
      <td>${m.pos||'—'}</td>
      <td>${m.l?`<span class="sl-level">HSK${m.l}</span>`:'—'}</td>
      <td><b>${ROLE[x.r]||x.r}</b></td>
      <td>${m.m||'—'}</td>
    </tr>`;
  }).join('');
  return `<div class="sl-analysis-head">
      <div class="mini">ĐÁP ÁN</div>
      <div class="sl-answer-zh">${slAcceptedAnswers(item).map((a,i)=>slAcceptedAnswers(item).length>1?`<div>${i+1}. ${a}</div>`:a).join('')}</div>
      <div class="sl-answer-py">${pinyin(cleanParts)}</div>
      <div class="sl-formula"><b>Công thức:</b> ${prepFormula}</div>
      <div style="margin-top:9px"><b>Giải thích:</b> ${item.explain}</div>
      <div class="sl-source-note">Pinyin, từ loại và cấp HSK lấy từ kho HSK1–3 của Sentence Lab.</div>
    </div>
    <div class="table-wrap" style="border:0;border-radius:0">
      <table class="sl-analysis-table"><thead><tr><th>Từ/cụm</th><th>Pinyin</th><th>Từ loại</th><th>Cấp</th><th>Vai trò trong câu</th><th>Nghĩa</th></tr></thead><tbody>${rows}</tbody></table>
    </div>`;
}

q('#slCheck').addEventListener('click',()=>{
  if(slAnswered)return;
  const item=slSession[slCurrent],ans=q('#slQAnswer').value.trim();
  if(!ans){q('#slFeedback').className='sl-feedback bad';q('#slFeedback').textContent='Hãy nhập câu trả lời trước.';return}
  const ok=sameSLItem(ans,item);
  slAnswered=true;
  slState.attempts.push({id:item.id,grammar:item.grammar,type:item.type,correct:ok,at:Date.now()});
  if(!ok)slState.wrong.push({id:item.id,grammar:item.grammar,type:item.type,wrong:ans,answer:slAcceptedAnswers(item).join(' / '),at:Date.now()});
  saveSL();
  q('#slFeedback').className='sl-feedback '+(ok?'good':'bad');
  q('#slFeedback').innerHTML=ok
    ?'✓ Chính xác. Hãy đọc đáp án, Pinyin và phần phân tích bên dưới trước khi sang câu tiếp theo.'
    :'✕ Chưa đúng. Hãy đối chiếu đáp án và xem cấu trúc đúng ở phần phân tích bên dưới.';
  q('#slAnalysis').innerHTML=slAnalysisHTML(item);
  q('#slAnalysis').classList.remove('hidden');
  q('#slNextBar').classList.remove('hidden');
  q('#slQAnswer').disabled=true;q('#slCheck').disabled=true;q('#slHint').disabled=true;
  q('#slAnalysis').scrollIntoView({behavior:'smooth',block:'nearest'});
  updateSLStats();
});
q('#slHint').addEventListener('click',()=>{
  if(!slSession.length||slCurrent>=slSession.length)return;
  const item=slSession[slCurrent];
  q('#slFeedback').className='sl-feedback good';
  const prepId=window.SL_ACTIVE_PREP_ID||null;
  const hint=(prepId&&item?.prepFormulaMap?.[prepId])||item.hint;
  q('#slFeedback').innerHTML=`<b>Gợi ý cấu trúc:</b> ${hint}`;
});
q('#slSkip').addEventListener('click',()=>{if(slCurrent<slSession.length){slCurrent++;renderSLQ()}});
q('#slNext').addEventListener('click',()=>{if(slCurrent<slSession.length){slCurrent++;renderSLQ()}});

function renderSLErrors(){
  const rows=slState.wrong.slice().reverse().slice(0,100).map(e=>`
    <tr><td>${G.get(e.grammar)?.name||e.grammar}</td><td>${MODES[e.type]||e.type}</td><td>${e.wrong}</td><td>${e.answer}</td></tr>`).join('');
  q('#slErrorRows').innerHTML=rows||'<tr><td colspan="4" class="mini">Chưa có lỗi nào trong Sentence Lab.</td></tr>';
}
q('#slClearErrors').addEventListener('click',()=>{
  if(confirm('Xóa toàn bộ lịch sử lỗi của Sentence Lab?')){
    slState={attempts:[],wrong:[]};saveSL();renderSLErrors();
  }
});

// Enter checks the current sentence before it is answered.
// After an answer, Enter moves to the next sentence.
q('#slQAnswer').addEventListener('keydown',e=>{
  if(e.key==='Enter'&&!e.shiftKey){
    e.preventDefault();
    if(slAnswered) q('#slNext').click();
    else q('#slCheck').click();
  }
});



// ---------------- HÁN NGỮ TẬP 1–2 · ĐỐI CHIẾU PREP ----------------
const HANYU_GRAMMAR_BANK=[{"id":"hanyu-001","book":1,"title":"吗 · câu hỏi Yes/No","formula":"Câu trần thuật + 吗？","status":"covered","prep":"Trợ từ nghi vấn 吗","note":"Trùng trực tiếp với PREP HSK1.","grammarId":"ma"},{"id":"hanyu-002","book":1,"title":"不 · phủ định","formula":"不 + V/Adj","status":"covered","prep":"Phủ định với 不","note":"Giữ làm nền cho các cấu trúc phủ định.","grammarId":"degree"},{"id":"hanyu-003","book":1,"title":"很 / 不太 / 太……了","formula":"S + 很/不太 + Adj；S + 太 + Adj + 了","status":"covered","prep":"很；不太；太……了","note":"Hán ngữ dùng lại nhóm mức độ nền tảng.","grammarId":"degree"},{"id":"hanyu-004","book":1,"title":"这 / 那 + lượng từ + danh từ","formula":"这/那 + M + N","status":"covered","prep":"这 / 那 + Lượng từ + Danh từ","note":"Mẫu chỉ định cơ bản.","grammarId":null},{"id":"hanyu-005","book":1,"title":"哪 + lượng từ + danh từ","formula":"哪 + M + N？","status":"expanded","prep":"这 / 那 + Lượng từ + Danh từ","note":"Hán ngữ đặt 哪 cạnh nhóm chỉ định để đối chiếu.","grammarId":"hy_na"},{"id":"hanyu-006","book":1,"title":"几 + lượng từ + danh từ","formula":"几 + M + N？","status":"covered","prep":"Từ nghi vấn 几","note":"Hỏi số lượng nhỏ/đếm được.","grammarId":null},{"id":"hanyu-007","book":1,"title":"多少 + danh từ","formula":"多少 + N？","status":"covered","prep":"多少 + Danh từ","note":"Hỏi số lượng không xác định.","grammarId":null},{"id":"hanyu-008","book":1,"title":"多少钱 / cách hỏi giá","formula":"N + 多少钱？","status":"covered","prep":"Hỏi giá với 多少钱","note":"Được dùng trong ngữ cảnh mua bán.","grammarId":null},{"id":"hanyu-009","book":1,"title":"什么 làm tân ngữ","formula":"V + 什么？","status":"expanded","prep":"做什么 / 干什么；什么 làm tân ngữ","note":"PREP có qua nhiều bài; Hán ngữ gom thành mẫu hỏi vật/nội dung.","grammarId":"hy_shenme_o"},{"id":"hanyu-010","book":1,"title":"谁 / 谁的","formula":"谁？；谁的 + N？","status":"expanded","prep":"谁 / 谁的 trong bài câu tồn hiện","note":"Tách rõ người và sở hữu.","grammarId":"hy_shei"},{"id":"hanyu-011","book":1,"title":"怎么 / 怎么样","formula":"怎么 + V？；……怎么样？","status":"covered","prep":"怎么；怎么样；phân biệt 怎么/怎么样","note":"Có thể dùng làm cặp so sánh trực tiếp.","grammarId":null},{"id":"hanyu-012","book":1,"title":"的 · sở hữu và định ngữ","formula":"N/Đại từ + 的 + N","status":"covered","prep":"Trợ từ kết cấu 的 chỉ sở hữu/định ngữ","note":"Mẫu nền tảng.","grammarId":null},{"id":"hanyu-013","book":1,"title":"的 · lược trung tâm ngữ","formula":"Định ngữ + 的（+ N bị lược）","status":"covered","prep":"Kết cấu chữ 的 — lược trung tâm ngữ","note":"PREP đã có ở HSK2.","grammarId":null},{"id":"hanyu-014","book":1,"title":"会 · năng lực đã học","formula":"S + 会 + V + O","status":"covered","prep":"会 — năng lực đã học","note":"Phân biệt với 会 dự đoán trong ngữ cảnh khác.","grammarId":null},{"id":"hanyu-015","book":1,"title":"能 · khả năng/điều kiện","formula":"S + 能 + V (+O)","status":"covered","prep":"Động từ năng nguyện 能","note":"PREP đã có.","grammarId":null},{"id":"hanyu-016","book":1,"title":"可以 · có thể/được phép","formula":"S + 可以 + V","status":"new","prep":"","note":"Hán ngữ dùng để mở rộng nhóm động từ năng nguyện.","grammarId":"hy_keyi"},{"id":"hanyu-017","book":1,"title":"想 · muốn/dự định","formula":"S + 想 + V + O","status":"covered","prep":"Động từ năng nguyện 想","note":"PREP đã có.","grammarId":null},{"id":"hanyu-018","book":1,"title":"想 và 要 · phân biệt sắc thái","formula":"想 + V ↔ 要 + V/N","status":"expanded","prep":"想；要","note":"Hán ngữ nhấn mạnh phân biệt mức độ ý định/nhu cầu.","grammarId":"hy_xiang_yao"},{"id":"hanyu-019","book":1,"title":"在 · chỉ vị trí","formula":"S + 在 + Place","status":"covered","prep":"在 làm động từ chỉ vị trí","note":"PREP đã có.","grammarId":null},{"id":"hanyu-020","book":1,"title":"在 + địa điểm + V","formula":"S + 在 + Place + V (+O)","status":"covered","prep":"Địa điểm làm trạng ngữ của hành động","note":"PREP đã có.","grammarId":null},{"id":"hanyu-021","book":1,"title":"在 / 正 / 正在 + V","formula":"S + 在/正/正在 + V (+呢)","status":"covered","prep":"在 + V biểu thị hành động đang tiến hành","note":"Có bài luyện Sentence Lab.","grammarId":"zai"},{"id":"hanyu-022","book":1,"title":"呢 · hỏi lại/xác nhận ngữ cảnh","formula":"N/Đại từ + 呢？；Mệnh đề + 呢","status":"expanded","prep":"Trợ từ ngữ khí 呢","note":"Hán ngữ mở rộng sắc thái theo ngữ cảnh.","grammarId":"hy_ne_context"},{"id":"hanyu-023","book":1,"title":"和 / 跟 nối người hoặc danh từ","formula":"A + 和/跟 + B","status":"covered","prep":"和 nối danh từ；A 跟/和 B + V","note":"PREP đã có nhiều ngữ cảnh.","grammarId":null},{"id":"hanyu-024","book":1,"title":"跟/和……一起","formula":"A + 跟/和 + B + 一起 + V","status":"covered","prep":"A 跟/和 B 一起 + V","note":"Có bài luyện Sentence Lab.","grammarId":"gen_yiqi"},{"id":"hanyu-025","book":1,"title":"先……再……","formula":"先 + V₁，再 + V₂","status":"covered","prep":"先；再","note":"Sentence Lab đã có cấu trúc tổng hợp.","grammarId":"xian_zai"},{"id":"hanyu-026","book":1,"title":"一边……一边……","formula":"S + 一边 + V₁，一边 + V₂","status":"covered","prep":"一边……一边……","note":"Có bài luyện Sentence Lab.","grammarId":"yi_bian"},{"id":"hanyu-027","book":1,"title":"边……边…… · khẩu ngữ","formula":"S + 边 + V₁，边 + V₂","status":"covered","prep":"边……边……","note":"Biến thể khẩu ngữ của 一边……一边…….","grammarId":"yi_bian"},{"id":"hanyu-028","book":1,"title":"一下儿 · làm nhẹ hành động","formula":"V + 一下儿；V + Pron + 一下儿；V + 一下儿 + N","status":"covered","prep":"一下儿","note":"PREP đã tách nhiều vị trí tân ngữ.","grammarId":null},{"id":"hanyu-029","book":1,"title":"别 / 不要 · mệnh lệnh phủ định","formula":"别/不要 + V (+O)","status":"covered","prep":"别 + V；不要……了","note":"Dùng cho yêu cầu/ngăn cản.","grammarId":null},{"id":"hanyu-030","book":1,"title":"请 / 请问","formula":"请 + V；请问，+ câu hỏi","status":"covered","prep":"请 trong lời mời/yêu cầu；请 và 请问","note":"PREP đã có.","grammarId":null},{"id":"hanyu-031","book":1,"title":"động-tân ly hợp","formula":"V + thành phần số lượng/định ngữ + O","status":"covered","prep":"请假、唱歌、放假","note":"Hán ngữ dùng lại nhóm động-tân ly hợp.","grammarId":null},{"id":"hanyu-032","book":2,"title":"常 / 常常 / 经常 / 总是","formula":"常/常常/经常 + V；总是 + V/Adj","status":"covered","prep":"常、常常、经常 và 总是","note":"PREP HSK2 đã có.","grammarId":null},{"id":"hanyu-033","book":2,"title":"有时 / 有时候","formula":"有时（候）+ Câu","status":"covered","prep":"有时 / 有时候","note":"PREP đã có.","grammarId":null},{"id":"hanyu-034","book":2,"title":"有时……有时……","formula":"有时 + A，有时 + B","status":"covered","prep":"有时……有时……","note":"PREP đã có.","grammarId":null},{"id":"hanyu-035","book":2,"title":"或者 / 还是 / 要么","formula":"A 或者 B；A 还是 B？；要么 A，要么 B","status":"expanded","prep":"还是","note":"Hán ngữ mở rộng hệ lựa chọn beyond 还是.","grammarId":"hy_choice_full"},{"id":"hanyu-036","book":2,"title":"又 và 再","formula":"又 + V（đã lặp）；再 + V（sẽ lặp）","status":"covered","prep":"又 và 再","note":"PREP HSK2 đã có đối chiếu.","grammarId":"you_zai"},{"id":"hanyu-037","book":2,"title":"又……又……","formula":"又 + Adj₁ + 又 + Adj₂ / 又 + V₁ + 又 + V₂","status":"new","prep":"","note":"Điểm Hán ngữ bổ sung rõ ràng; khác 一边……一边…… ở quan hệ song song đặc điểm/hành động.","grammarId":"hy_you_you"},{"id":"hanyu-038","book":2,"title":"又……又…… vs 一边……一边……","formula":"又A又B ↔ 一边V₁一边V₂","status":"new","prep":"","note":"Hán ngữ nhấn mạnh phân biệt hai cấu trúc dễ nhầm.","grammarId":"hy_you_yibian_diff"},{"id":"hanyu-039","book":2,"title":"的时候","formula":"Cụm/Mệnh đề + 的时候，Mệnh đề","status":"covered","prep":"……的时候","note":"PREP HSK1 đã có.","grammarId":null},{"id":"hanyu-040","book":2,"title":"以前 / 以后","formula":"V/Time + 以前/以后","status":"expanded","prep":"前/后；từ thời gian tương đối","note":"Hán ngữ hệ thống hóa trước/sau theo mốc hoặc hành động.","grammarId":"hy_yiqian_yihou"},{"id":"hanyu-041","book":2,"title":"了 · hoàn thành/thay đổi","formula":"V + 了；……了","status":"covered","prep":"了 cuối câu；了 sau động từ","note":"PREP đã tách nhiều chức năng.","grammarId":"le"},{"id":"hanyu-042","book":2,"title":"过 · kinh nghiệm","formula":"S + V + 过 + O","status":"covered","prep":"Trợ từ động thái 过","note":"Có bài luyện Sentence Lab.","grammarId":"guo"},{"id":"hanyu-043","book":2,"title":"着 · trạng thái duy trì","formula":"S + V + 着 + O","status":"covered","prep":"着 — trạng thái/hành động đang duy trì","note":"Có bài luyện Sentence Lab.","grammarId":"zhe"},{"id":"hanyu-044","book":2,"title":"每……都……","formula":"每 + M/N + 都 + vị ngữ","status":"covered","prep":"每 — mỗi, mọi","note":"Có bài luyện Sentence Lab.","grammarId":"mei_dou"},{"id":"hanyu-045","book":2,"title":"lặp động từ","formula":"A→AA / A一A；AB→ABAB","status":"covered","prep":"Lặp động từ đơn âm tiết / hai âm tiết","note":"PREP HSK2 đã có.","grammarId":null},{"id":"hanyu-046","book":2,"title":"马上 / sắp xảy ra","formula":"马上 + V；要/快/快要/就要 + V + 了","status":"covered","prep":"马上；要/快/快要/就要……了","note":"Có nhóm luyện tương ứng.","grammarId":"kuaiyao"},{"id":"hanyu-047","book":2,"title":"离 · khoảng cách","formula":"A + 离 + B + khoảng cách","status":"covered","prep":"Giới từ 离","note":"Có bài luyện Sentence Lab.","grammarId":"li"},{"id":"hanyu-048","book":2,"title":"从……到……","formula":"从 + điểm đầu + 到 + điểm cuối","status":"covered","prep":"从……到……","note":"Có bài luyện Sentence Lab.","grammarId":"cong_dao"},{"id":"hanyu-049","book":2,"title":"向 / 往 · phương hướng","formula":"向/往 + hướng/địa điểm + V","status":"covered","prep":"向；往","note":"Có bài luyện Sentence Lab.","grammarId":"xiang_wang"},{"id":"hanyu-050","book":2,"title":"比 · so sánh hơn","formula":"A + 比 + B + Adj","status":"covered","prep":"Câu so sánh với 比","note":"Có bài luyện Sentence Lab.","grammarId":"bi"},{"id":"hanyu-051","book":2,"title":"没有 · so sánh không bằng","formula":"A + 没有 + B + Adj","status":"covered","prep":"So sánh “không bằng” với 没有","note":"Nằm trong nhóm 比/没有.","grammarId":"bi"},{"id":"hanyu-052","book":2,"title":"比较 + tính từ","formula":"比较 + Adj","status":"covered","prep":"比较 + Tính từ","note":"PREP HSK2 đã có.","grammarId":"bi"},{"id":"hanyu-053","book":2,"title":"mức chênh lệch trong câu 比","formula":"A + 比 + B + Adj + 一点儿/得多/多了/数量","status":"covered","prep":"Mức chênh lệch trong câu 比","note":"Hán ngữ dùng để mở rộng so sánh.","grammarId":"bi"},{"id":"hanyu-054","book":2,"title":"有点儿 / 一点儿 / 一些","formula":"有点儿 + Adj/V；Adj + 一点儿；一点儿/一些 + N","status":"covered","prep":"有点儿 / 一点儿 / 一些","note":"Có bài luyện Sentence Lab.","grammarId":"youdian"},{"id":"hanyu-055","book":2,"title":"得 · bổ ngữ trạng thái","formula":"V + 得 + Adj；V + O + V + 得 + Adj","status":"covered","prep":"Bổ ngữ trạng thái với 得","note":"Có bài luyện Sentence Lab.","grammarId":"de_comp"},{"id":"hanyu-056","book":2,"title":"因为……所以……","formula":"因为 + nguyên nhân，所以 + kết quả","status":"covered","prep":"因为……所以……","note":"Có bài luyện Sentence Lab.","grammarId":"yinwei"},{"id":"hanyu-057","book":2,"title":"虽然……但是……","formula":"虽然 + mệnh đề 1，但是 + mệnh đề 2","status":"covered","prep":"虽然……但是……","note":"Có bài luyện Sentence Lab.","grammarId":"suiran"},{"id":"hanyu-058","book":2,"title":"就 / 才","formula":"Time/điều kiện + 就/才 + V","status":"covered","prep":"才和就；就 + V","note":"Có bài luyện Sentence Lab.","grammarId":"jiu_cai"},{"id":"hanyu-059","book":2,"title":"可能 / 不可能","formula":"可能/不可能 + V/Chủ-vị","status":"covered","prep":"可能 / 不可能","note":"Có bài luyện Sentence Lab.","grammarId":"keneng"},{"id":"hanyu-060","book":2,"title":"对 · đối với","formula":"A + 对 + B + Adj/V","status":"covered","prep":"Giới từ 对","note":"Có bài luyện Sentence Lab.","grammarId":"dui"},{"id":"hanyu-061","book":2,"title":"是……的","formula":"S + 是 + thành phần nhấn mạnh + V + 的","status":"covered","prep":"是……的","note":"Có bài luyện Sentence Lab.","grammarId":"shi_de"},{"id":"hanyu-062","book":2,"title":"bổ ngữ kết quả","formula":"V + 完/好/错/对/懂/到/见/走","status":"covered","prep":"Bổ ngữ kết quả","note":"PREP HSK2 đã có.","grammarId":null},{"id":"hanyu-063","book":2,"title":"看 / 看见 / 看到","formula":"看 + N；看见/看到 + O","status":"covered","prep":"看；看见和看到","note":"Hán ngữ dùng để phân biệt hành động và kết quả.","grammarId":null},{"id":"hanyu-064","book":2,"title":"听 / 听到 / 听见 / 听说","formula":"听 + âm thanh；听到/听见 + nội dung；听说 + mệnh đề","status":"covered","prep":"听；听到/听见；听说","note":"PREP HSK1 đã có.","grammarId":null},{"id":"hanyu-065","book":2,"title":"说 / 说话","formula":"说 + nội dung；A 跟/和 B 说话","status":"covered","prep":"说和说话","note":"PREP HSK1 đã có.","grammarId":null},{"id":"hanyu-066","book":2,"title":"见 / 见面","formula":"见 + người；A 跟/和 B 见面","status":"covered","prep":"见和见面","note":"PREP HSK1 đã có.","grammarId":null},{"id":"hanyu-067","book":2,"title":"找 / 找到","formula":"找 + O；找到 + O","status":"covered","prep":"找和找到","note":"Phân biệt hành động tìm và kết quả tìm thấy.","grammarId":null},{"id":"hanyu-068","book":2,"title":"来 / 去 trong bổ ngữ phương hướng","formula":"V + 来/去","status":"expanded","prep":"进来/进去；出来/出去；回来/回去","note":"Hán ngữ hệ thống hóa hướng về/xa người nói.","grammarId":"hy_lai_qu"}];
function hanyuStatusLabel(s){return s==='covered'?'✅ PREP đã có':s==='expanded'?'🟡 PREP có · Hán ngữ mở rộng':'🆕 Hán ngữ bổ sung'}
function hanyuFiltered(){
  const book=q('#hanyuBook')?.value||'ALL',status=q('#hanyuStatus')?.value||'ALL',s=(q('#hanyuSearch')?.value||'').trim().toLowerCase();
  return HANYU_GRAMMAR_BANK.filter(x=>(book==='ALL'||x.book===+book)&&(status==='ALL'||x.status===status)&&(!s||`${x.title} ${x.formula} ${x.prep} ${x.note}`.toLowerCase().includes(s)))
}
function updateHanyuKPIs(){
  if(!q('#hanyuTotal'))return;
  q('#hanyuTotal').textContent=HANYU_GRAMMAR_BANK.length;
  q('#hanyuCovered').textContent=HANYU_GRAMMAR_BANK.filter(x=>x.status==='covered').length;
  q('#hanyuExpanded').textContent=HANYU_GRAMMAR_BANK.filter(x=>x.status==='expanded').length;
  q('#hanyuNew').textContent=HANYU_GRAMMAR_BANK.filter(x=>x.status==='new').length;
}
function renderHanyuCatalog(){
  if(!q('#hanyuCatalog'))return;
  const rows=hanyuFiltered(); q('#hanyuMatch').textContent=`${rows.length} mục phù hợp`; q('#hanyuCatalogCount').textContent=`${rows.length} mục`;
  if(!rows.length){q('#hanyuCatalog').innerHTML='<div class="hanyu-empty">Không có điểm Hán ngữ phù hợp bộ lọc.</div>';return}
  const books=[1,2].filter(b=>rows.some(x=>x.book===b));
  q('#hanyuCatalog').innerHTML=books.map(book=>{
    const items=rows.filter(x=>x.book===book);
    const note=book===1?'Tập 1 · nền tảng HSK1–đầu HSK2 · phần đã xác minh':'Tập 2 · HSK2–3 · phần đã xác minh';
    return `<div class="hanyu-book-section"><div class="hanyu-book-head"><div><h4>Hán ngữ Tập ${book}</h4><div class="hanyu-book-note">${note}</div></div><span class="pill">${items.length} mục</span></div><div class="hanyu-grid">${items.map(x=>`<div class="hanyu-card ${x.grammarId?'is-practice':''}"><div class="hanyu-card-top"><div class="hanyu-card-title">${x.title}</div><span class="hanyu-badge ${x.status}">${hanyuStatusLabel(x.status)}</span></div><div class="hanyu-formula">${x.formula}</div>${x.prep?`<div class="hanyu-prep"><b>PREP liên quan:</b> ${x.prep}</div>`:''}${x.note?`<div class="hanyu-note">${x.note}</div>`:''}<div class="hanyu-actions">${x.grammarId?`<button class="btn secondary hanyu-practice" data-gid="${x.grammarId}">Luyện trong Sentence Lab</button><span class="hanyu-practice-ready">✓ Thực chiến</span>`:`<span class="mini">Chưa có bài Sentence Lab riêng</span>`}</div></div>`).join('')}</div></div>`
  }).join('');
  qa('.hanyu-practice').forEach(b=>b.addEventListener('click',()=>{
    setSLTab('practice');
    if(q('#slLevel'))q('#slLevel').value='ALL';
    refreshSLGrammar();
    if(q('#slGrammar')&&[...q('#slGrammar').options].some(o=>o.value===b.dataset.gid)){q('#slGrammar').value=b.dataset.gid;refreshSLVocab();updateSLMatchInfo()}
    q('#slPanelPractice')?.scrollIntoView({behavior:'smooth',block:'start'})
  }))
}
window.HANYU_GRAMMAR_BANK=HANYU_GRAMMAR_BANK;
function initHanyu(){
  if(!q('#hanyuCatalog'))return; updateHanyuKPIs();renderHanyuCatalog();
  q('#hanyuBook')?.addEventListener('change',renderHanyuCatalog);q('#hanyuStatus')?.addEventListener('change',renderHanyuCatalog);q('#hanyuSearch')?.addEventListener('input',renderHanyuCatalog);
  q('#hanyuReset')?.addEventListener('click',()=>{q('#hanyuBook').value='ALL';q('#hanyuStatus').value='ALL';q('#hanyuSearch').value='';renderHanyuCatalog()})
}


