const PASS7_UNRESOLVED=["SX1-2","SX1-73","SX1-83","SX1-84","SX1-90","SX1-142","SX1-144","SX1-166","SX1-176","SX1-179","SX1-195","SX1-208","SX1-241","SX1-242","SX1-264","SX1-271","SX1-276","SX1-302","SX1-309","SX1-336","SX1-339","SX2-64","SX2-234","SX2-442","SX2-581"];

function p7Refs(item){
  return [...new Set([...(item?.sourceRefs||[]),...(item?.trainingRefs||[]),item?.trainingRef].filter(Boolean))];
}
function p7AddRefs(item,refs){
  item.sourceRefs=[...new Set([...p7Refs(item),...(refs||[])])];
  return item;
}
function p7FindRef(ref){
  return BANK.find(x=>p7Refs(x).includes(ref));
}
function p7FindExact(answer){
  const k=pass4Norm(answer);
  return BANK.find(x=>x.type==='reorder'&&pass4Norm(x.answer)===k);
}
function p7Parts(tokens){
  return (tokens||[]).map(t=>({t,r:/^[，。！？,.!?；;：:、]$/.test(t)?'Punc':'X'}));
}
const PASS7_STATS={
  sourceRepairs:PASS7_SOURCE_REPAIRS.length,
  sourceMerged:PASS7_SOURCE_MERGED.length,
  multiSources:PASS7_MULTI.length,
  duplicateLinks:PASS7_DUPLICATE_LINKS.length,
  sourceLinks:PASS7_SOURCE_LINKS.length,
  sourceExclusions:PASS7_SOURCE_EXCLUSIONS.length,
  unresolved:PASS7_UNRESOLVED.length,
  added:0,linkedExisting:0,removedSuperseded:0,multiEnriched:0,duplicateLinked:0
};

// Replace the incomplete pre-Pass7 fragment before adding its source-verified merged sentence.
for(let i=BANK.length-1;i>=0;i--){
  if(BANK[i].type==='reorder'&&p7Refs(BANK[i]).includes('SX2-230')){
    BANK.splice(i,1); PASS7_STATS.removedSuperseded++;
  }
}

function p7Integrate(r,opts={}){
  let existing=p7FindExact(r.answer);
  if(existing){
    p7AddRefs(existing,r.sourceRefs||[r.ref]);
    existing.grammarLinks=[...new Set([...(existing.grammarLinks||[]),...(r.grammarLinks||[])])].filter(x=>PASS4_CANON_IDS.has(x));
    if(r.acceptedAnswers?.length){
      existing.acceptedAnswers=[...new Set([...(existing.acceptedAnswers||[existing.answer]),...r.acceptedAnswers])];
      existing.pass7Multi=true;
      PASS7_STATS.multiEnriched++;
    }
    existing.pass7SourceVerified=existing.pass7SourceVerified||!!opts.sourceVerified;
    PASS7_STATS.linkedExisting++;
    return existing;
  }
  const gm=G.get(r.grammar)||G.get('general_order');
  const tokens=r.correctedTokens||r.tokens||[];
  const q={
    type:'reorder',
    grammar:r.grammar||'general_order',
    grammarLinks:(r.grammarLinks||[]).filter(x=>PASS4_CANON_IDS.has(x)),
    topic:r.acceptedAnswers?.length?'Sắp xếp câu · nhiều đáp án hợp lệ':'Sắp xếp câu · source-verified',
    parts:p7Parts(tokens),
    tokens:[...tokens],
    answer:r.answer,
    acceptedAnswers:r.acceptedAnswers?.length?[...r.acceptedAnswers]:undefined,
    vi:'',
    hint:gm?.formula||'Sắp xếp theo trật tự câu tự nhiên',
    explain:r.acceptedAnswers?.length
      ?'Câu này có nhiều trật tự tự nhiên được chấp nhận. Chỉ cần khớp một đáp án đã QA.'
      :(gm?.explain||'Đáp án đã được đối chiếu lại với nguồn gốc.'),
    level:r.level||2,
    source:'Ngữ pháp chuẩn',displaySource:'',
    trainingRef:r.ref,
    sourceRefs:[...(r.sourceRefs||[r.ref])],
    trainingLesson:r.lesson||'',trainingPage:r.page??null,
    verification:r.verification||'Pass 7',
    pass7SourceVerified:!!opts.sourceVerified,
    pass7Multi:!!r.acceptedAnswers?.length
  };
  addQ(q); PASS7_STATS.added++;
  return q;
}

for(const r of PASS7_SOURCE_REPAIRS) p7Integrate(r,{sourceVerified:true});
for(const r of PASS7_SOURCE_MERGED) p7Integrate(r,{sourceVerified:true});
for(const r of PASS7_MULTI) p7Integrate(r,{sourceVerified:false});

// Link source records that should not create another physical exercise.
for(const l of PASS7_SOURCE_LINKS){
  for(const t of l.targets){
    const item=p7FindRef(t);
    if(item)p7AddRefs(item,[l.ref]);
  }
}
// Link the 26 duplicate source occurrences to their representative exercise.
for(const d of PASS7_DUPLICATE_LINKS){
  const item=p7FindRef(d.target);
  if(item){p7AddRefs(item,[d.ref]);PASS7_STATS.duplicateLinked++;}
}
PASS7_STATS.totalBank=BANK.length;
PASS7_STATS.reorderCount=BANK.filter(x=>x.type==='reorder').length;
PASS7_STATS.canonicalCoverage=new Set(BANK.flatMap(slGrammarIds)).size;
PASS7_STATS.multiExercises=BANK.filter(x=>Array.isArray(x.acceptedAnswers)&&x.acceptedAnswers.length>1).length;
window.SL_PASS7_SOURCE_REPAIRS=PASS7_SOURCE_REPAIRS;
window.SL_PASS7_SOURCE_MERGED=PASS7_SOURCE_MERGED;
window.SL_PASS7_MULTI=PASS7_MULTI;
window.SL_PASS7_STATS=PASS7_STATS;
